let lang='en';try{lang=localStorage.getItem('popomo-language')==='zh'?'zh':'en';}catch{}
function translate(){document.documentElement.lang=lang==='en'?'en':'zh-CN';document.querySelector('#flow-language').value=lang;document.title=lang==='en'?'About us · POPOMO':'关于我们 · POPOMO';document.querySelectorAll('[data-about-zh]').forEach(el=>el.innerHTML=el.dataset[lang==='en'?'aboutEn':'aboutZh']);const social=document.querySelectorAll('.about-social-card');social[0].setAttribute('aria-label',lang==='en'?'POPOMO Facebook, opens in a new tab':'POPOMO Facebook，打开新窗口');social[1].setAttribute('aria-label',lang==='en'?'POPOMO Instagram, opens in a new tab':'POPOMO Instagram，打开新窗口');}
document.querySelector('#flow-language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('popomo-language',lang);}catch{}translate();};translate();
const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!reduced.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('is-waiting');observer.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll('.about-reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('is-waiting');observer.observe(el);}});document.addEventListener('focusin',e=>{e.target.closest('.about-reveal')?.classList.remove('is-waiting');});reduced.addEventListener('change',()=>{if(reduced.matches){observer.disconnect();document.querySelectorAll('.is-waiting').forEach(el=>el.classList.remove('is-waiting'));}});}
